"""Additional workbench action descriptions and parameter schemas."""
from case_crypto import CODECS,CIPHERS

def register(action,field,FILE):
    def f(key,label,default='',kind='text',hint='',options=None,when=None):
        value=field(key,label,default,kind,hint,options)
        if when:value['when']=when
        return value
    def add(key,group,title,description,fields,task):
        action(key,group,title,'取证工作台',description,fields,'python casework.py '+task+' --args 本次参数文件 --out {output}',output='evidence',casework=task,private_arguments=task in ('codec','cipher','mount','hash'))
    def source():return [f('source','输入来源','text','select',options=['text','file']),f('input_file','输入文件（可选）','','optional_file',when={'source':['file']}),f('input_format','文本的字节表示','utf8','select',options=['utf8','hex','base64'],when={'source':['text']}),f('text','输入文本','','textarea',when={'source':['text']})]
    add('mounted_files','mount','浏览挂载盘 / 导入文件','只浏览本工作区创建的只读挂载卷；文件导入任务目录后可继续在工具台分析。',[f('drive','盘符','R','select',options=list('RSTUVWXYZ')),f('mode','操作','list','select',options=['list','import']),f('relative','挂载盘内相对路径','')],'mounted')
    add('hex_view','inspect','交互式十六进制查看','按页查看大文件，支持定位、字节选择和跳转到搜索命中；不需一次加载整份镜像。',[FILE('04_archive/carrier.bin'),f('offset','字节偏移','0'),f('length','每页字节数','256','select',options=['128','256','512','1024','4096'])],'hex')
    add('byte_search','inspect','搜索 HEX / UTF-8 / UTF-16LE 字节','全文件流式检索，命中可以直接跳到十六进制视图。',[FILE('04_archive/carrier.bin'),f('pattern','检索值','504b0304'),f('pattern_format','检索值表示','hex','select',options=['hex','utf8','utf16le','base64']),f('offset','开始字节偏移','0'),f('scan_mib','最多扫描 MiB（0=全文件）','0')],'search')
    add('binary_patch','inspect','在副本中修改指定字节','用于签名、宽高等已定位的修复；可核对预期原字节，输出副本后继续校验。',[FILE('02_png/broken_header.png'),f('offset','补丁字节偏移','0'),f('expected','预期原字节 HEX（建议填写）',''),f('replacement','新字节 HEX','89504e470d0a1a0a')],'patch')
    add('separate_files','archive','自动分离嵌入文件','类似 binwalk 的常用分离路线：扫描签名，按 PNG / JPEG / ZIP / GIF / PDF / 压缩流等结构定界，记录来源后导出。',[FILE('04_archive/carrier.bin'),f('scan_mib','扫描 MiB（0=全文件）','0'),f('max_files','最多导出文件','64'),f('budget_mib','总导出预算 MiB','128'),f('depth','继续扫描导出文件的深度','1','select',options=['0','1','2','3'])],'separate')
    common=[FILE('05_disk/tiny_fat16.dd'),f('sector','分区起始扇区（留空自动识别）',''),f('sector_size','逻辑扇区字节数','512','select',options=['512','4096'])]
    add('disk_inventory','disk','浏览镜像文件与删除项','直接浏览 RAW / E01 / VMDK / VHD 的目录，不需要系统挂载；先验证文件系统起点，再按路径筛选。',common+[f('mode','目录范围','all','select',options=['all','deleted']),f('filter','路径包含（可留空）',''),f('rows','网页最多显示条目','1000')],'inventory')
    add('disk_batch_recover','disk','批量恢复删除文件 / 导出目录','按当前镜像的元数据编号逐项恢复，记录原路径、扇区、大小和 SHA256；不完整内容单独标为 .partial。',common+[f('mode','导出范围','deleted','select',options=['deleted','all']),f('filter','原路径包含（可留空）',''),f('max_files','最多导出文件','64'),f('budget_mib','总导出预算 MiB','256')],'recovery')
    add('disk_photorec','disk','PhotoRec 数据恢复','文件系统结构受损或目录恢复失败时，按签名恢复常见格式；输入限附件镜像，不扫描物理磁盘。',[FILE('05_disk/tiny_fat16.dd'),f('partition','镜像分区布局','auto','select','裸分区 / 单载体选 none；整盘通常选 auto。',['auto','none']),f('types','恢复类型（英文逗号分隔）','jpg,png,zip,pdf,txt'),f('seconds','本次最多秒数','300'),f('budget_mib','恢复空间预算 MiB','256')],'photorec')
    add('disk_image_convert','disk','VMDK / E01 / VHD 转 RAW 副本','通过 TSK 的镜像后端读取逻辑字节，可继续恢复、分离和按分区挂载；必须备齐相邻分片。',[FILE('05_disk/tiny_fat16.dd'),f('budget_mib','RAW 输出预算 MiB','2048')],'convert')
    add('disk_extundelete','disk','Ext3 / Ext4 日志恢复','Kali 使用 extundelete；Windows 提供无需挂载的恢复替代入口。必须在未挂载的分区工作副本上执行。',[FILE('05_disk/tiny_fat16.dd'),f('selector','恢复范围','all','select',options=['all','inode','file']),f('inode','inode','2',when={'selector':['inode']}),f('path','分区内相对路径','Flag.txt',when={'selector':['file']})],'extundelete')
    add('browser_history','disk','Firefox / Chromium 浏览历史','识别 places.sqlite / History 的实际表结构，联合访问记录与 URL，保留原始时间并换算 UTC。',[FILE('06_sqlite/case.db'),f('rows','最多返回记录','500')],'browser')
    add('disk_mount','mount','只读挂载 / 卸载镜像','提供 ImDisk RAW 分区、Windows ISO/VHD/VHDX、VeraCrypt 与旧 TrueCrypt 容器入口；首次准备驱动或系统操作可能需要 UAC。',[FILE('05_disk/tiny_fat16.dd'),f('mode','操作','plan','select',options=['plan','status','mount','unmount','install_imdisk']),f('method','挂载方式','imdisk','select',options=['imdisk','windows','veracrypt','truecrypt']),f('drive','盘符','R','select',options=list('RSTUVWXYZ')),f('sector','分区起始扇区','0'),f('sector_size','扇区字节数','512','select',options=['512','4096']),f('password','已知容器口令','','password',when={'method':['veracrypt','truecrypt']}),f('pim','PIM（可留空）','',when={'method':['veracrypt']}),f('keyfile','密钥文件（可选）','','optional_file',when={'method':['veracrypt','truecrypt']})],'mount')
    add('codec','crypto','编码转换 / 凯撒 / XOR / 核心价值观','文本或文件都可输入，保留字节输出；支持候选枚举，转换结果可继续进入下一步。',source()+[f('operation','转换方法','base64_decode','select',options=CODECS),f('shift','移动位数（正数向后、负数向前）','13',when={'operation':['caesar','ascii_shift']}),f('key','XOR 密钥','',when={'operation':['xor']}),f('key_format','密钥表示','hex','select',options=['hex','utf8','base64'],when={'operation':['xor']}),f('encoding','输入文本编码','utf-8','select',options=['utf-8','utf-16le','gb18030']),f('mapping','逐字符替换表 JSON','{}','textarea',when={'operation':['replace']})],'codec')
    add('cipher','crypto','AES / DES / 3DES / RC4 / XOR','用已知密钥和 IV 加解密；支持 CBC、ECB、CTR、GCM，GCM 验证 tag。不会假装从任意密文自动恢复密钥。',source()+[f('algorithm','算法与模式','AES-CBC','select',options=CIPHERS),f('direction','操作方向','decrypt','select',options=['decrypt','encrypt']),f('key','已知密钥','','password'),f('key_format','密钥表示','hex','select',options=['hex','utf8','base64']),f('iv','IV / nonce（HEX）',''),f('padding','填充方式','pkcs7','select',options=['pkcs7','none']),f('tag','GCM tag（HEX，解密必填）','',when={'algorithm':['AES-GCM']}),f('aad','GCM AAD（HEX，可留空）','',when={'algorithm':['AES-GCM']})],'cipher')
    add('hash_tools','crypto','摘要计算与口令候选验证','计算摘要，或用有依据的小字典验证 MD5 / SHA / NTLM。哈希命中仍需到原加密对象上验证。',source()+[f('mode','功能','calculate','select',options=['calculate','dictionary']),f('algorithm','候选验证算法','md5','select',options=['md5','sha1','sha256','sha512','ntlm'],when={'mode':['dictionary']}),f('target','目标摘要','',when={'mode':['dictionary']}),f('words','候选口令（每行一个）','','textarea',when={'mode':['dictionary']}),f('wordlist','已导入字典（可选）','','optional_file',when={'mode':['dictionary']})],'hash')
    add('memory_triage','automation','内存题分流分析（Vol3 / Vol2）','按题意运行进程、历史、文件 / MFT、注册表、口令线索或容器路线；保留每个插件的输出和失败条件。',[FILE('memory.raw'),f('version','Volatility 版本','3','select',options=['3','2']),f('profile','已核对的 Vol2 profile','',when={'version':['2']}),f('route','题目目标','general','select',options=['general','history','files','registry','credentials','container','clipboard'])],'memory')
    action('vol_artifacts','memory','Vol3 · MFT / 驻留数据 / 系统线索','Volatility 3','根据题意选插件；MFT 驻留内容、网络连接和口令线索各有不同前提。',[FILE('memory.raw'),f('plugin','插件','mftscan.MFTScan','select',options=['mftscan.MFTScan','mftscan.ResidentData','mftscan.ADS','netscan','envars','dlllist','malware.malfind','truecrypt.Passphrase','registry.hashdump'])], 'python $v3 -f {file} windows.{plugin}',ram=True)
    action('vol_registry','memory','Vol3 · 注册表 Hive 与键值','Volatility 3','先查 hivelist，再以本镜像的 Hive 偏移与 Select 键判断活动 ControlSet，查看主机名等键值。',[FILE('memory.raw'),f('plugin','注册表插件','hivelist','select',options=['hivelist','printkey','hivescan']),f('address','Hive 虚拟偏移（可留空）',''),f('key','相对 Hive 的键路径','Select')], 'python $v3 -f {file} windows.registry.{plugin}',ram=True)
    action('vol2_artifacts','memory2','Vol2 · 剪贴板 / MFT / 口令与容器','Volatility 2','使用随包标准插件；notepad 适用范围有限，失败可转进程页检索。master key 与容器 keyfile 不是同一概念。',[FILE('memory.raw'),f('profile','已验证 profile',''),f('plugin','插件','clipboard','select',options=['clipboard','notepad','mftparser','hashdump','truecryptsummary','truecryptpassphrase','truecryptmaster','netscan','envars','screenshot'])], 'vol2 -f {file} --profile={profile} {plugin}',ram=True,output='artifacts')
    action('vol2_registry','memory2','Vol2 · 注册表 Hive 与键值','Volatility 2','从 hivelist 获取当前 Hive 偏移，printkey 先看 Select，再选择实际 ControlSet 的 ComputerName 键。',[FILE('memory.raw'),f('profile','已验证 profile',''),f('plugin','注册表插件','hivelist','select',options=['hivelist','printkey']),f('address','Hive 虚拟偏移（printkey 可选）',''),f('key','相对 Hive 的键路径','Select')], 'vol2 -f {file} --profile={profile} {plugin}',ram=True)
    action('vol_extra','memory','Vol3 · pypykatz / BitLocker 社区扩展','Volatility 3 社区插件','pypykatz 从离线镜像解析 LSASS 凭据；BitLocker 返回内存密钥候选。先核对系统、进程和加密卷，再判断是否可用。',[FILE('memory.raw'),f('plugin','社区插件','vol_pypykatz.pypykatz','select',options=['vol_pypykatz.pypykatz','bitlocker.BitlockerFVEKScan']),f('dump','导出原始密钥候选','no','select',options=['no','yes'],when={'plugin':['bitlocker.BitlockerFVEKScan']}),f('tags','池标签（逗号分隔；空值用默认）','',when={'plugin':['bitlocker.BitlockerFVEKScan']})], 'vol3 -f {file} {plugin}',ram=True,output='extensions',json_grid=True)
    action('vol2_extra','memory2','Vol2 · mimikatz / BitLocker / Editbox','Volatility 2 扩展与控件分析','mimikatz 适用于其支持的旧系统 WDigest；BitLocker 结果需匹配卷格式。Editbox 已内置，不重复安装同名插件。',[FILE('memory.raw'),f('profile','已验证 profile',''),f('plugin','插件','mimikatz','select',options=['mimikatz','bitlocker','editbox']),f('pid','控件所属 PID（可留空）','',when={'plugin':['editbox']}),f('dump','导出候选文件','no','select',options=['no','yes'],when={'plugin':['bitlocker','editbox']})], 'vol2 -f {file} --profile={profile} {plugin}',ram=True,output='extensions')
